sweater_orders = []
for o in orders:
    for item in o.get('order_items', []):
        name = (item.get('product_name') or '').lower()
        if 'sweater' in name:
            sweater_orders.append(o)
            break

print('orders with sweater keyword', len(sweater_orders))
# pick most recent by created_at
from datetime import datetime

def parse_dt(s):
    try:
        return datetime.fromisoformat(s.replace('Z',''))
    except Exception:
        return datetime.min

if sweater_orders:
    latest = max(sweater_orders, key=lambda o: parse_dt(o.get('created_at')))
    print('latest sweater order_id', latest['order_id'], 'created_at', latest.get('created_at'))
    for item in latest.get('order_items', []):
        if 'sweater' in (item.get('product_name') or '').lower():
            print('item', item)
else:
